const D = { density: .55, energy: .62, speed: 1, scale: 1, fold: .5, persist: .9, hue: 215, x: .5, y: .5, style: 'spiral-fold', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const BW = Math.max(360, Math.min(520, Math.round(width / 2.6))), BH = Math.max(80, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.dens = new Float32Array(BW * BH); S.zsum = new Float32Array(BW * BH);
  S.bw = BW; S.bh = BH; S.px = 0.1; S.py = 0.1; S.pz = 0.1;
}
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1); S.pj = fr(2) * 2 - 1; S.px = 0.1 + fr(3) * 0.6; S.py = fr(4) * 0.6; S.pz = 0.1 + fr(5) * 0.4;
}

const g = S.g, dens = S.dens, zsum = S.zsum;
const styleI = P.style === 'plasma' ? 1 : P.style === 'ember' ? 2 : P.style === 'ice' ? 3 : P.style === 'pencil' ? 4 : 0;
const sec = K.section;

// Rossler ODE constants — drift c continuously so the fold sharpens/relaxes over minutes
const a = 0.2, b = 0.2;
const cBase = 5.2 + P.fold * 4.6;               // higher c = sharper, more chaotic fold
const c = cBase + 0.9 * Math.sin(K.t * 0.020) + (sec - 3.5) * 0.10 + S.pj * 0.35 + A.lowmid * 0.6;
const dt = 0.021;
const fit = 1 / 13, cx = 0, cy = 0, cz = 6;      // recenter the scroll band

// continuous incommensurate 3D rotation = the motion floor (never re-phases on K.t)
const rotRate = 0.085 + P.speed * 0.13;
const ay = K.t * rotRate + A.rms * 0.35 * Math.sin(K.t * 0.6);
const ax = 0.52 + 0.30 * Math.sin(K.t * 0.041);
const cay = Math.cos(ay), say = Math.sin(ay), cax = Math.cos(ax), sax = Math.sin(ax);
const view = Math.min(BW, BH) * 0.44 * P.scale;
const hbw = BW * 0.5, hbh = BH * 0.5;

// fade the density field (trail persistence)
const decay = 0.78 + P.persist * 0.20;
for (let i = 0, n = BW * BH; i < n; i++) { dens[i] *= decay; zsum[i] *= decay; }

// integrate the Rossler system MANY steps/frame and splat into the fading buffer
let x = S.px, y = S.py, z = S.pz;
const steps = Math.round((38000 + P.density * 34000) * (BW * BW) / 40000);   // 38k..72k iterates/frame, scaled by buffer area (oldBW 200)
for (let s = 0; s < steps; s++) {
  const dx = -y - z, dy = x + a * y, dz = b + z * (x - c);
  x += dx * dt; y += dy * dt; z += dz * dt;
  if (!(x > -1e4 && x < 1e4) || !(y > -1e4 && y < 1e4) || !(z > -1e4 && z < 1e4)) { x = 0.1; y = 0.1; z = 0.1; continue; }
  const nx = (x - cx) * fit, ny = (y - cy) * fit, nz = (z - cz) * fit;
  const rx = nx * cay - nz * say;
  const rz0 = nx * say + nz * cay;
  const ry = ny * cax - rz0 * sax;
  const bxi = (hbw + rx * view) | 0, byi = (hbh - ry * view) | 0;
  if (bxi >= 0 && bxi < BW && byi >= 0 && byi < BH) {
    const bi = byi * BW + bxi;
    dens[bi] += 1;
    zsum[bi] += z;                                // accumulate raw z for depth color (fold = high z)
  }
}
S.px = x; S.py = y; S.pz = z;

// iq cosine palette (rgb 0..1)
function pal(m) {
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + 0.00)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + 0.33)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + 0.66))];
}
const hueBase = ((P.hue + S.hoff * 50 + sec * 10) % 360) / 360;
const expo = 0.55 + P.energy * 2.2 + K.intensity * 0.45 + A.bass * 1.3;

g.loadPixels();
const px = g.pixels;
for (let j = 0; j < BH; j++) {
  const cyn = j / BH - 0.5;
  for (let i = 0; i < BW; i++) {
    const bi = j * BW + i;
    const d = dens[bi];
    const dn = 1 - Math.exp(-d * expo * 0.028);   // log-mapped density -> brightness
    const zavg = d > 0.0001 ? zsum[bi] / d : 0;
    const depth = Math.min(1, Math.max(0, zavg / 12));  // 0 = in-plane blue spiral, 1 = hot fold
    const cxn = i / BW - 0.5;
    const vig = Math.exp(-(cxn * cxn + cyn * cyn) * 2.5);
    let r, gg, bl;
    if (styleI === 1) { // plasma — iq cosine cycling by depth, luminous
      const cc = pal(depth * 0.85 + dn * 0.25 + hueBase);
      const sh = 0.28 + 0.72 * dn;
      const lift = 0.16 * vig;
      r = cc[0] * sh + lift * 0.5; gg = cc[1] * sh + lift * 0.4; bl = cc[2] * sh + lift * 0.7;
    } else if (styleI === 2) { // ember — black ground, coals to white-hot fold
      const m = dn * (0.55 + depth * 0.8);
      r = Math.min(1, Math.max(0, m * 2.0 - 0.02));
      gg = Math.min(1, Math.max(0, m * 1.7 - 0.55));
      bl = Math.min(1, Math.max(0, m * 2.4 - 1.8));
      const lift = 0.03 * vig; r += lift * 0.4; gg += lift * 0.08;
    } else if (styleI === 3) { // ice — cryo cyan/white on deep navy, cold
      const m = dn;
      const gr = 0.05 + 0.06 * vig;
      r = gr * 0.4 + m * m * 0.85 + depth * 0.05;
      gg = gr * 0.7 + m * (0.55 + depth * 0.35);
      bl = gr * 1.3 + m * (0.75 + 0.25 * (1 - depth));
      r = Math.min(1, r); gg = Math.min(1, gg); bl = Math.min(1, bl);
    } else if (styleI === 4) { // pencil — graphite hatch on warm paper (named mono)
      const tex = 0.8 + 0.35 * ((Math.sin(i * 12.9 + j * 78.2) * 43758.5) % 1);
      const hatch = 0.8 + 0.2 * Math.sin((i + j) * 0.9);
      const ink = Math.pow(dn, 0.8) * tex * hatch;
      const tone = 1 - Math.min(1, ink) * 0.88;
      r = 0.93 * tone; gg = 0.905 * tone; bl = 0.84 * tone;
    } else { // spiral-fold (default): deep-blue in-plane spiral -> hot-orange fold, glowing on dark
      const rr = Math.min(1, 0.12 + depth * 1.7);
      const gr2 = Math.min(1, Math.max(0, depth * 0.95 - 0.03));
      const br2 = Math.min(1, Math.max(0, 0.62 - depth * 1.25) + 0.08);
      const bright = 0.85 + 0.55 * dn;
      const lift = 0.14 + 0.24 * vig;
      const gR = 0.10 * lift, gG = 0.07 * lift, gB = 0.42 * lift;  // deep-blue ambient ground
      r = Math.min(1, gR + rr * dn * bright);
      gg = Math.min(1, gG + gr2 * dn * bright);
      bl = Math.min(1, gB + br2 * dn * bright);
    }
    const o = 4 * bi;
    px[o] = r * 255; px[o + 1] = gg * 255; px[o + 2] = bl * 255; px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio-reactive bloom on the bass — partial ADD tint, never full-frame flash (won't strobe)
if ((A.bass > 0.02 || A.treble > 0.02) && styleI !== 4) {
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass * 0.5 + A.treble * 0.35) * (0.4 + P.energy * 0.6);
  fill((P.hue + 25) % 360, 50, 100, glow * 18);
  ellipse(P.x * width, P.y * height, width * 0.85, height * 0.85);
  blendMode(BLEND); pop();
}
